export const DEFAULT_SETTINGS={version:1,columns:5,hoverPreview:true,includeRanking:true,hideWatched:false,inactiveMonths:12,interests:'',request:''};
export function normalizeSettings(value={}){return {...DEFAULT_SETTINGS,columns:[4,5].includes(value.columns)?value.columns:5,hoverPreview:value.hoverPreview!==false,includeRanking:value.includeRanking!==false,hideWatched:value.hideWatched===true,inactiveMonths:[3,6,12,24].includes(value.inactiveMonths)?value.inactiveMonths:12,interests:typeof value.interests==='string'?value.interests.trim().slice(0,1000):'',request:typeof value.request==='string'?value.request.trim().slice(0,4000):''};}
export function customizationBrief(settings){const s=normalizeSettings(settings);return `# 我的拾藏需求\n\n兴趣：${s.interests||'未填写'}\n\n我想怎样使用：${s.request||'浏览关注和收藏，减少挑选时间。'}\n\n已选设置：桌面${s.columns}列；悬停预览${s.hoverPreview?'开':'关'}；榜单${s.includeRanking?'混入':'关闭'}；看完的视频${s.hideWatched?'隐藏':'保留'}；停更${s.inactiveMonths}个月。\n\n请先读项目AGENTS.md和FORK_GUIDE.md，根据以上要求修改现有工程。读取我本人授权的B站关注、收藏和稍后再看；不要使用模板作者的数据，不导出登录凭证。不确定的内容留空，不把读取失败当作没有投稿。先实现、运行和验证，再报告结果；发布由我决定。\n`;}
